# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İNSANDA MERKEZÎ SİNİR SİSTEMİ (BEYİN VE OMURİLİK BÖLÜMLERİ)</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Ön Beyin (En Büyük Kısım)</text>\n  <text x="40" y="102" font-size="11" font-weight="bold" fill="#1e40af">• Uç Beyin (Beyin Kabuğu):</text>\n  <text x="48" y="119" font-size="10.5" fill="#475569">İstemli hareket, beş duyu, zekâ,</text>\n  <text x="48" y="135" font-size="10.5" fill="#475569">hafıza, konuşma (Dış boz, iç ak).</text>\n  <text x="40" y="158" font-size="11" font-weight="bold" fill="#1e40af">• Ara Beyin:</text>\n  <text x="48" y="175" font-size="10.5" fill="#475569">Talamus (koku hariç duyu santrali)</text>\n  <text x="48" y="191" font-size="10.5" fill="#475569">Hipotalamus (homeostazi, hipofiz)</text>\n  <text x="48" y="207" font-size="10.5" fill="#475569">Epitalamus (melatonin, biyolojik saat)</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Orta ve Arka Beyin</text>\n  <text x="262" y="102" font-size="11" font-weight="bold" fill="#166534">• Orta Beyin:</text>\n  <text x="270" y="119" font-size="10.5" fill="#475569">Görme-işitme refleksi, kas tonusu.</text>\n  <text x="262" y="142" font-size="11" font-weight="bold" fill="#166534">• Arka Beyin:</text>\n  <text x="270" y="159" font-size="10.5" fill="#475569">- Beyincik: Denge ve kas uyumu</text>\n  <text x="270" y="176" font-size="10.5" fill="#475569">- Pons: Yarım küreler arası bağ</text>\n  <text x="270" y="193" font-size="10.5" fill="#475569">- Omurilik Soğanı: Hayat düğümü</text>\n  <text x="270" y="209" font-size="10.5" fill="#475569">(solunum, dolaşım, yutma, kusma).</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Omurilik ve Meninges</text>\n  <text x="485" y="102" font-size="11" font-weight="bold" fill="#854d0e">• Meninges Zarları:</text>\n  <text x="493" y="119" font-size="10.5" fill="#475569">Sert zar, Örümceksi zar (BOS), İnce zar</text>\n  <text x="485" y="142" font-size="11" font-weight="bold" fill="#854d0e">• Omurilik:</text>\n  <text x="493" y="159" font-size="10.5" fill="#475569">- Dışta ak, içte kelebek boz madde</text>\n  <text x="493" y="176" font-size="10.5" fill="#475569">- Refleks ve alışkanlık merkezi</text>\n  <text x="493" y="193" font-size="10.5" fill="#475569">- Duyu nöronları arka (dorsal),</text>\n  <text x="493" y="209" font-size="10.5" fill="#475569">motor nöronlar ön (ventral) kökten.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UÇ BEYİN LOBLARI VE KESİT MADDE DÜZENİ KARŞILAŞTIRMASI</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Beyin Kabuğu (Korteks) Lobları</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• Ön (Frontal) Lob: İstemli kas hareketleri,</text>\n  <text x="60" y="120" font-size="10.5" fill="#475569">problem çözme, karar verme, konuşma (Broca).</text>\n  <text x="50" y="142" font-size="11" fill="#334155">• Yan (Parietal) Lob: Dokunma, acı, basınç, tat.</text>\n  <text x="50" y="164" font-size="11" fill="#334155">• Şakak (Temporal) Lob: İşitme, koku, hafıza.</text>\n  <text x="50" y="186" font-size="11" fill="#334155">• Art Kafa (Oksipital) Lob: Görme merkezi.</text>\n  <text x="185" y="215" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Nasırlı Cisim ve Beyin Üçgeni yarım küreleri bağlar</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Boz Madde ve Ak Madde Dağılımı</text>\n  <text x="380" y="108" font-size="11.5" font-weight="bold" fill="#991b1b">• Dışta Boz, İçte Ak Madde Olanlar:</text>\n  <text x="392" y="128" font-size="11" fill="#334155">- Uç Beyin (Serebral Korteks)</text>\n  <text x="392" y="146" font-size="11" fill="#334155">- Beyincik (Hayat Ağacı görünümü)</text>\n  <text x="380" y="176" font-size="11.5" font-weight="bold" fill="#991b1b">• Dışta Ak, İçte Boz Madde Olanlar:</text>\n  <text x="392" y="196" font-size="11" fill="#334155">- Omurilik Soğanı (Bulbus)</text>\n  <text x="392" y="214" font-size="11" fill="#334155">- Omurilik (Enine kesitte kelebek şekli)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇEVRESEL SİNİR SİSTEMİ: SOMATİK VE OTONOM SİNİRLER</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Somatik Sinir Sistemi (İstemli)</text>\n  <text x="50" y="105" font-size="11" fill="#334155">• İskelet (çizgili) kaslarını kontrol eder.</text>\n  <text x="50" y="128" font-size="11" fill="#334155">• Miyelinli duyu ve motor nöronlardan oluşur;</text>\n  <text x="60" y="146" font-size="10.5" fill="#475569">impuls iletim hızı oldukça yüksektir.</text>\n  <text x="50" y="172" font-size="11" fill="#334155">• Yürüme, yazı yazma, koşma, konuşma gibi</text>\n  <text x="60" y="190" font-size="10.5" fill="#475569">bilinçli davranışları uç beyinle yürütür.</text>\n  <text x="185" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">12 Çift Kafa Siniri · 31 Çift Omurilik Siniri</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Otonom Sinir Sistemi (İstemsiz)</text>\n  <text x="380" y="105" font-size="11" fill="#334155">• İç organları, düz kasları ve bezleri yönetir.</text>\n  <text x="380" y="128" font-size="11" fill="#334155">• Sempatik Sinirler (Heyecan / Savaş ya da Kaç):</text>\n  <text x="390" y="146" font-size="10.5" fill="#475569">Kalp atışını hızlandırır, göz bebeğini büyütür,</text>\n  <text x="390" y="162" font-size="10.5" fill="#475569">bronşları genişletir, sindirimi yavaşlatır.</text>\n  <text x="380" y="185" font-size="11" fill="#334155">• Parasempatik Sinirler (Dinlen ve Sindir):</text>\n  <text x="390" y="203" font-size="10.5" fill="#475569">Kalbi yavaşlatır, sindirimi ve tükürüğü artırır</text>\n  <text x="390" y="219" font-size="10.5" fill="#475569">(10. kafa siniri Vagus parasempatik etkilidir).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
